<?php require_once __DIR__.'/chart_local.php'; function jobrunplot($width=550,$height=400){$r=db_query("SELECT SUM(entries),UNIX_TIMESTAMP(date) FROM job_history WHERE mode='p' AND date>=DATE_SUB(NOW(),INTERVAL 3 WEEK) GROUP BY date ORDER BY date","ro");$p=[];while($x=mysqli_fetch_row($r))$p[]=[date('m-d',(int)$x[1]),(float)$x[0]];echo '<div id="jobrunchart_div">'.atlas_chart_line($p,'Installation Running Jobs',$width,$height).'</div>';}
